const paymentMoney = cents => (cents/100).toLocaleString('de-DE',{style:'currency',currency:'EUR'});
const latestPayment = payment => payment.history.at(-1);
function paymentBalances(snapshot){const balance=snapshot.captured-snapshot.fees-snapshot.refunded-snapshot.payoutSent;return {balance,available:balance-snapshot.held-snapshot.pending,inTransit:snapshot.payoutSent-snapshot.bank};}
function appendPaymentObservation(payment,step,time){
  const vendor=paymentSources.find(s=>s.id===payment.id),previous=latestPayment(payment);
  const n=String(payment.history.length+1).padStart(3,'0'),prefix=`PAY-${payment.id.toUpperCase()}-${n}`;
  const observation={captured:0,fees:0,refunded:0,held:0,pending:0,payoutSent:0,bank:0,expected:0,dispute:false,...previous,...step,bankEvidence:!!step.bankEvidence,time,sourceId:`SRC-${prefix}`,factId:`FAC-${prefix}`,reservationId:null,commitmentId:null};
  const balances=paymentBalances(observation),before=previous?paymentBalances(previous):{balance:0};
  const relatedBase=[payment.orderEvent,...(previous?[previous.factId]:[])];
  const sourceName=step.bankEvidence?'Bankauszug (Demo)':vendor.name;
  const raw=step.bankEvidence?{demo:true,schema:'blackbox.demo.bank.v1',source:sourceName,bank_entry_ref:'DEMO-BANK-SP-1',payout_ref:payment.payout,currency:'EUR',amount_cents:observation.bank-(previous?.bank||0),booking_status:'booked',booked_at:`2026-10-31T${time}+01:00`}:{demo:true,schema:'blackbox.demo.payment.v1',source:sourceName,event:step.event,provider:vendor.name,transaction_ref:payment.transaction,order_ref:payment.order,payout_ref:observation.payoutSent||observation.expected?payment.payout:null,currency:'EUR',captured_cents:observation.captured,fee_cents:observation.fees,refunded_cents:observation.refunded,held_cents:observation.held,pending_cents:observation.pending,payout_sent_cents:observation.payoutSent,bank_matched_cents:observation.bank,expected_payout_cents:observation.expected,dispute_open:observation.dispute,observed_at:`2026-10-31T${time}+01:00`};
  const extras=[];
  const delta=balances.balance-before.balance;
  if(delta!==0)extras.push({id:`MOV-${prefix}`,type:'movement',title:`${vendor.short} · Provider-Guthaben ${delta>0?'+':''}${paymentMoney(delta)}`,detail:`Veränderung des Provider-Guthabens aus diesem Ereignis: ${paymentMoney(delta)}. ${step.message} Diese Buchung ist keine bestätigte Bankgutschrift.`,quote:`Provider-Guthaben zuvor ${paymentMoney(before.balance)} → danach ${paymentMoney(balances.balance)}. Zahlungen, Gebühren, Erstattungen und Auszahlungen sind bereits enthalten.`,proof:'Provider-Bewegung · Demo · kein Bankbeleg'});
  if(observation.bank>(previous?.bank||0))extras.push({id:`MOV-BANK-${prefix}`,type:'movement',title:`Demo-Bank · +${paymentMoney(observation.bank-(previous?.bank||0))}`,detail:'Separater fiktiver Bankeingang mit passender Auszahlungsreferenz. Die Auszahlung wird vom Betrag unterwegs in den bestätigten Bankbestand umgeordnet; sie ist kein neuer Umsatz.',quote:`Bankbeleg DEMO-BANK-SP-1 · ${payment.payout} · EUR · ${paymentMoney(observation.bank)}`,proof:'Separater Bankauszug · ausdrücklich simuliert'});
  if(observation.held!==(previous?.held||0)){observation.reservationId=`RES-${prefix}`;extras.push({id:observation.reservationId,type:'reservation',title:`${vendor.short} · ${paymentMoney(observation.held)} gebunden`,detail:`Aktueller Einbehalt bzw. vorgemerkte Erstattung: ${paymentMoney(observation.held)}. ${step.message} Die Bindung verändert die Verfügbarkeit, nicht nochmals das gesamte Provider-Guthaben.`,quote:`Gebunden zuvor ${paymentMoney(previous?.held||0)} → aktuell ${paymentMoney(observation.held)}`,proof:'Versionierter Einbehalt · Demo',status:observation.held?'Gebunden':'Freigegeben'});}else observation.reservationId=previous?.reservationId||null;
  if(observation.expected!==(previous?.expected||0)){observation.commitmentId=`COM-${prefix}`;extras.push({id:observation.commitmentId,type:'commitment',title:`${vendor.short} · ${paymentMoney(observation.expected)} Auszahlung angekündigt`,detail:`Noch angekündigter Auszahlungsbetrag: ${paymentMoney(observation.expected)}. Eine Ankündigung zählt noch nicht als Bewegung. ${step.message}`,quote:`Angekündigt ${paymentMoney(observation.expected)} · Referenz ${payment.payout}`,proof:'Versionierte Auszahlungsankündigung · Demo',status:observation.expected?'Offen':'Abgegangen'});}else observation.commitmentId=previous?.commitmentId||null;
  events.push({id:observation.sourceId,type:'source',title:`${sourceName} · ${step.label}`,source:sourceName,time,entity:`${payment.order} · ${payment.transaction}`,detail:step.message,quote:JSON.stringify(raw,null,2),related:[observation.factId,...relatedBase],proof:step.bankEvidence?'Fiktiver Bankbeleg · keine Bankanbindung':'Schema-neutrale Demo-Meldung · kein echter API-Payload'});
  events.push({id:observation.factId,type:'fact',title:`${vendor.short} · ${step.label}`,source:step.bankEvidence?`${vendor.name} + Bankauszug (Demo)`:sourceName,time,entity:`${payment.order} · ${payment.transaction}`,detail:`${step.message} Stand: ${paymentMoney(balances.balance)} beim Provider, davon ${paymentMoney(observation.pending)} in Abwicklung und ${paymentMoney(observation.held)} gebunden; ${paymentMoney(balances.inTransit)} zur Bank unterwegs; ${paymentMoney(observation.bank)} per Demo-Bankbeleg zugeordnet.`,quote:`Eingezogen ${paymentMoney(observation.captured)} − Gebühren ${paymentMoney(observation.fees)} − Erstattungen ${paymentMoney(observation.refunded)} − abgegangene Auszahlungen ${paymentMoney(observation.payoutSent)} = ${paymentMoney(balances.balance)} beim Provider.`,related:[observation.sourceId,...extras.map(e=>e.id),...relatedBase],proof:'Abgeleiteter Zahlungsstand · letzter bekannter Demo-Stand'});
  for(const event of extras)events.push({...event,source:sourceName,time,entity:payment.transaction,related:[observation.sourceId,observation.factId,...relatedBase]});
  payment.history.push(observation);return observation;
}
function seedPayments(){
  paymentDemo.forEach((payment,i)=>{
    payment.orderEvent=`SRC-PAY-ORDER-${i+1}`;
    events.push({id:payment.orderEvent,type:'source',title:`${payment.shop} · Auftrag ${payment.order}`,source:payment.shop,time:`10:41:${50+i*2}`,entity:payment.order,detail:'Eigenständiger Auftrag für die Zahlungsdemo. Er gehört nicht zu den Rechnungs- oder Cash-Beispielen. Shopify Payments und Stripe sind hier getrennte Demo-Zahlungskonten mit unterschiedlichen Aufträgen.',quote:`Auftrag ${payment.order}\nBetrag ${paymentMoney(payment.amount)}\nTransaktion ${payment.transaction}`,related:[],proof:'Shop-Auftrag · Zahlungsdemo'});
    const first=appendPaymentObservation(payment,payment.steps[0],`10:41:${51+i*2}`);
    events.find(e=>e.id===payment.orderEvent).related=[first.sourceId,first.factId];
  });events.sort((a,b)=>a.time.localeCompare(b.time));
}
function paymentTotals(){return paymentDemo.reduce((total,payment)=>{const last=latestPayment(payment),balance=paymentBalances(last);for(const key of ['captured','fees','refunded','held','pending','bank','expected'])total[key]+=last[key];for(const key of ['balance','available','inTransit'])total[key]+=balance[key];if(last.dispute)total.disputes++;return total},{captured:0,fees:0,refunded:0,held:0,pending:0,bank:0,expected:0,balance:0,available:0,inTransit:0,disputes:0})}
function paymentEventIsCurrent(event){
  if(event.id.startsWith('RES-PAY-'))return paymentDemo.some(p=>latestPayment(p).reservationId===event.id&&latestPayment(p).held>0);
  if(event.id.startsWith('COM-PAY-'))return paymentDemo.some(p=>latestPayment(p).commitmentId===event.id&&latestPayment(p).expected>0);
  return true;
}
function paymentAnswer(){const total=paymentTotals();return {type:'payments',title:`${paymentMoney(total.bank)} per Demo-Bankbeleg bestätigt.`,text:`${paymentMoney(total.captured)} eingezogen, ${paymentMoney(total.fees)} Gebühren und ${paymentMoney(total.refunded)} Erstattungen. Beim Provider liegen noch ${paymentMoney(total.balance)}: davon ${paymentMoney(total.pending)} in Abwicklung und ${paymentMoney(total.held)} gebunden. ${paymentMoney(total.inTransit)} sind ausgezahlt, aber noch ohne passenden Bankbeleg. ${total.disputes} offene Streitfälle.`,math:[[paymentMoney(total.available),'beim Provider verfügbar'],['',''],[paymentMoney(total.inTransit),'zur Bank unterwegs'],['',''],[paymentMoney(total.bank),'Bank · Demo-Beleg']],note:'Vier eigenständige Demo-Aufträge. Gebühren sind Beispielwerte. Auszahlungen verschieben Geld und zählen nicht als neuer Umsatz. Eine Provider-Meldung allein bestätigt keinen Bankeingang. Dieses Szenario ist getrennt von der Rechnungs- und Cash-Demo.',refs:paymentDemo.map(p=>latestPayment(p).factId),question:'Wo steckt mein Geld bei den Payment-Providern?'};}
function paymentDetail(id){
  const payment=paymentDemo.find(p=>p.id===id);if(!payment)return;
  const vendor=paymentSources.find(s=>s.id===id),last=latestPayment(payment),balance=paymentBalances(last),connected=state.sources.includes(id),done=payment.index===payment.steps.length-1;
  showOverlay(`${closeButton()}<div class="eyebrow">${icon('arrow')}ZAHLUNGSVERLAUF · DEMO</div><div class="billing-detail-heading">${sourceIcon(id)}<div><h2>${vendor.name}</h2><p>${payment.transaction} · ${payment.shop} ${payment.order}</p></div></div><div class="payment-position"><div><small>Beim Provider</small><strong>${paymentMoney(balance.balance)}</strong></div><div><small>Zur Bank unterwegs</small><strong>${paymentMoney(balance.inTransit)}</strong></div><div><small>Bank · Demo-Beleg</small><strong>${paymentMoney(last.bank)}</strong></div></div><p class="payment-current-status">${last.label}</p><dl class="detail-meta"><div><dt>Eingezogen brutto</dt><dd>${paymentMoney(last.captured)}</dd></div><div><dt>Gebühren · Beispielwerte</dt><dd>${paymentMoney(last.fees)}</dd></div><div><dt>Erstattungen abgeschlossen</dt><dd>${paymentMoney(last.refunded)}</dd></div><div><dt>Beim Provider in Abwicklung</dt><dd>${paymentMoney(last.pending)}</dd></div><div><dt>Einbehalten / vorgemerkt</dt><dd>${paymentMoney(last.held)}</dd></div><div><dt>Beim Provider verfügbar</dt><dd>${paymentMoney(balance.available)}</dd></div><div><dt>Auszahlung angekündigt</dt><dd>${paymentMoney(last.expected)}</dd></div><div><dt>Auszahlungsreferenz</dt><dd>${last.payoutSent||last.expected?payment.payout:'Noch keine'}</dd></div></dl><div class="billing-demo-controls">${connected?`<button class="btn primary full" data-action="payment-next" data-id="${id}" ${done?'disabled':''}>${icon('play')}${done?'Demo-Verlauf abgeschlossen':payment.steps[payment.index+1].bankEvidence?'Demo-Bankeingang abgleichen':'Nächstes Zahlungsereignis simulieren'}</button>${!done?`<p>Als Nächstes: ${payment.steps[payment.index+1].label}</p>`:''}`:`<button class="btn primary full" data-action="payment-activate" data-id="${id}">${icon('plus')}Demo-Quelle aktivieren</button><p>Spiele den Verlauf Schritt für Schritt durch.</p>`}</div><div class="eyebrow" style="font-size:9px">VERLAUF · NEUESTE ZUERST</div><div class="shipment-history">${payment.history.slice().reverse().map(observation=>`<div class="shipment-history-row"><i class="status-dot"></i><div><time>31.10. · ${observation.time} CET</time><h3>${observation.label}</h3><p>${observation.message}</p><button class="citation-btn" data-action="event" data-id="${observation.sourceId}">${observation.bankEvidence?'Demo-Bankbeleg':'Originalmeldung'} ${icon('arrow')}</button><button class="citation-btn" data-action="event" data-id="${observation.factId}">Abgeleiteter Fact ${icon('arrow')}</button></div></div>`).join('')}</div><button class="detail-link" data-action="event" data-id="${payment.orderEvent}">Shop-Auftrag ${payment.order} ${icon('arrow')}</button><div class="demo-callout">Fiktive Transaktionen und Gebühren. Keine echte Provider- oder Bankverbindung. Historische Ereignisse bleiben erhalten; Auszahlungen werden nicht doppelt als Einnahme gezählt.</div>`,true);
}
function paymentConnectionModal(source){const connected=state.sources.includes(source.id);showOverlay(`${closeButton()}<div style="margin-bottom:22px">${sourceIcon(source.id)}</div><h2>${source.name} ${connected?'verwalten.':'verbinden.'}</h2><p>${source.text}</p><div class="flow-summary"><div>${icon('plug')}<span>Zahlungsereignisse aufzeichnen<small>Transaktions-ID · Auftrag · Betrag · Währung · Status</small></span></div><div>${icon('arrow')}<span>Den Geldfluss nachvollziehen<small>Gebühren · Erstattungen · Guthaben · Auszahlungen</small></span></div><div>${icon('shield')}<span>Herkunft und Grenzen sichtbar halten<small>Provider-Meldung und Bankbeleg getrennt prüfen</small></span></div></div><div class="demo-callout">Ausgewählte simulierte Ereignisse. Live-Abdeckung und Auszahlungsdaten hängen von Anbieter, Konto und API-Berechtigungen ab. Es werden keine Zugangsdaten abgefragt.</div><button class="btn primary full" data-action="${connected?'payment-detail':'payment-activate'}" data-id="${source.id}">${icon('play')}${connected?'Zahlungsverlauf ausprobieren':'Demo aktivieren & Verlauf öffnen'}</button>${connected?`<button class="btn secondary full billing-disconnect" data-action="toggle-source" data-id="${source.id}">Demo-Quelle trennen</button>`:''}`)}
function advancePayment(id){const payment=paymentDemo.find(p=>p.id===id);if(!payment||!state.sources.includes(id)||payment.index>=payment.steps.length-1)return;state.elapsed++;payment.index++;appendPaymentObservation(payment,payment.steps[payment.index],currentTime());if(state.page==='app')document.getElementById('app-content').innerHTML=renderTab();paymentDetail(id);toast('Zahlungsereignis und verknüpfte Ableitungen aufgezeichnet.');}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(!action)return;const id=action.dataset.id;if(action.dataset.action==='payment-detail')paymentDetail(id);if(action.dataset.action==='payment-next')advancePayment(id);if(action.dataset.action==='payment-activate'){if(!paymentSources.some(s=>s.id===id))return;if(!state.sources.includes(id))state.sources.push(id);persist();if(state.page==='app')renderApp();paymentDetail(id);toast('Payment-Quelle für die Demo aktiviert.')}if(action.dataset.action==='payment-question'){state.answer='payments';navigate('answers')}});

function sourceJumpLinks(){return `<nav class="source-jump-links" aria-label="Quellenkategorien"><button data-action="source-jump" data-id="shops">${icon('box')}Shops & Business</button><button data-action="source-jump" data-id="payment">${icon('arrow')}Zahlungen & Auszahlungen</button><button data-action="source-jump" data-id="billing">${icon('list')}Rechnungen & Buchhaltung</button><button data-action="source-jump" data-id="tracking">${icon('truck')}Versandquellen</button></nav>`}
function paymentSourcesSection(){return `<section class="source-group payment-source-group" id="source-payment"><div class="source-group-heading"><div><h2>Zahlungen & Auszahlungen</h2><p>Vom Checkout bis zum Bankbeleg. Jeder Status hat einen Betrag, einen Auftrag und eine Herkunft.</p></div><button class="btn secondary small" data-action="payment-question">${icon('spark')}Wo steckt mein Geld?</button></div><div class="billing-flow-strip"><span>${icon('check')}Zahlung eingezogen</span>${icon('arrow')}<span>${icon('clock')}Beim Provider</span>${icon('arrow')}<span>${icon('arrow')}Auszahlung</span>${icon('arrow')}<span>${icon('shield')}Bankbeleg</span></div><div class="app-section-grid">${sources.filter(s=>s.category==='payment').map(sourceCard).join('')}</div><p class="payment-source-note">Vier eigenständige Demo-Konten. Shopify Payments und Stripe werden hier getrennt geführt. In einer echten Anbindung wird jede Transaktion über Konto und Provider-ID eindeutig zugeordnet.</p></section>`}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action="source-jump"]');if(action&&['shops','payment','billing','tracking'].includes(action.dataset.id))document.getElementById('source-'+action.dataset.id)?.scrollIntoView({behavior:'smooth',block:'start'})});
